const genericCategoryPrompt = (title: string, kind: string, duration: string) => "You are a senior AI video prompt engineer, visual director, continuity supervisor, cinematographer, production designer, sound designer, and quality-control editor. Create an ultra-detailed production-ready prompt for " + title + ".\n\nCATEGORY: " + title + "\nPROMPT TYPE: " + kind + "\nDURATION: " + duration + "\n\nCreate a complete result, not a vague concept. Define the subject, story objective, audience, location, environment geometry, props, mood, visual hierarchy, composition, camera height, shot size, lens, framing, depth of field, focus behavior, lighting direction, color grade, materials, texture, realistic motion, and final emotional beat.\n\nLOCKED CONTINUITY BIBLE\nBefore Scene 1, define every recurring character, presenter, creature, product, prop, and environment. Lock identity, face or product geometry, age, height, proportions, skin, fur, scales, hair, wardrobe, colors, accessories, voice, accent, movement style, signature props, location layout, time of day, weather, lighting direction, palette, and object state. Reuse the same references in every scene. Never redesign a locked element.\n\nSCENE ARCHITECTURE\nBuild connected scenes no longer than 10 seconds each unless the user specifies another clip length. Scene 1 must establish a strong hook. Every scene must have one clear objective, one action, precise timecodes, camera direction, lighting, dialogue or narration when needed, sound cues, an emotional beat, an ending state, and a handoff to the next scene. The ending pose, gaze, screen direction, hand position, object state, lighting, and emotion of Scene N must become the starting state of Scene N+1. Do not create disconnected montage shots, unexplained time jumps, prop drift, character drift, or random extras.\n\nAUDIO AND DIALOGUE\nAssign every line to one named speaker. Keep supplied dialogue exact. Use natural lip-sync, voice age, accent, pacing, pauses, emotion, ambience, Foley, and transitions. SFX must remain below speech. Never invent extra dialogue, narration, claims, or speakers. If the scene is an audience CTA, state which character speaks and keep all other characters silent.\n\nPLATFORM AND OUTPUT\nState platform, aspect ratio, pixel dimensions, frame rate, total duration, scene durations, safe zones, export format, and delivery notes. Default to 9:16 for Shorts, Reels, Stories, and TikTok; 16:9 for YouTube landscape and cinematic widescreen; 1:1 for square feeds; 4:5 for portrait feeds. Keep important faces, products, logos, and text inside safe margins. Reproduce requested text exactly and never create pseudo-text.\n\nNEGATIVE PROMPT\nNo identity drift, face morphing, species change, product redesign, wardrobe change, prop drift, inconsistent lighting, broken perspective, impossible reflections, malformed anatomy, extra fingers, broken hands, distorted eyes, duplicate characters, unexplained extras, flicker, jitter, frame popping, random cuts, unmotivated zooms, focus pumping, unreadable or misspelled text, accidental logos, watermarks, subtitles, captions, unsupported claims, compression artifacts, low-detail textures, or continuity breaks.\n\nFINAL OUTPUT\nReturn: task interpretation; locked character/product bible; locked environment bible; act structure for long videos; complete scene-by-scene prompts with exact timecodes and handoffs; camera, lighting, composition and motion instructions; exact dialogue, lip-sync, SFX and ambience; platform specifications; negative prompt; two controlled variations; and a final quality-control checklist confirming duration arithmetic, character consistency, scene continuity, audio synchronization, platform fit, and artifact prevention. Follow the category direction exactly and never shorten the production output into a one-line idea.";
const makePrompt = (title: string, kind: string, duration: string, index: number) => title === "Viral Baby Videos Creating Prompt" ? attachedBabyPrompt + viralBabyExactHandoffPrompt : title === "Ulti Dunya: Reverse Animal World" ? reverseAnimalPrompt : title === "Adaptive Multi-Scene AI Video Master Prompt" ? adaptiveMasterPrompt : title === "Cute Baby Talking Videos Master Prompt" ? cuteBabyTalkingPrompt : title === "Watermelon Sculpture Video Prompt" ? watermelonSculpturePrompt : missingVisualPrompts[title] ? missingVisualPrompts[title] : genericCategoryPrompt(title, kind, duration);
const allCategoryCards: CategoryCard[] = titles.map((title, index) => { const duration = index % 4 === 0 ? "60 sec" : index % 4 === 1 ? "2 min" : index % 4 === 2 ? "3 min" : "5 min"; const kind = chooseKind(title); return { id: index + 1, title, description: `A ready-made ${title.toLowerCase()} prompt with a clear visual hook, production direction, and scene-ready structure.`, kind, image: chooseRealImage(title, index), accent: accents[index % accents.length], duration, prompt: makePrompt(title, kind, duration, index) }; });

const previewCards = allCategoryCards.filter((card) => card.title === "Viral Baby Videos Creating Prompt" || card.title === "Ulti Dunya: Reverse Animal World" || card.title === "Adaptive Multi-Scene AI Video Master Prompt" || card.title === "Cute Baby Talking Videos Master Prompt" || card.title === "Watermelon Sculpture Video Prompt");
const remainingCards = allCategoryCards.filter((card) => !previewCards.includes(card));
export const categoryCards: CategoryCard[] = [...previewCards, ...remainingCards].map((card, index) => ({ ...card, id: index + 1 }));
